type FriendStatusBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *FriendStatusBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(FriendStatus{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	FriendStatusReset((*FriendStatus)(p))
	return true
}
func (b *FriendStatusBuilder) GetRoot() *FriendStatus {
	if b.Arena.Locked {
		return nil
	}
	return (*FriendStatus)(b.Arena.At(b.root))
}
func (b *FriendStatusBuilder) AsConst() *FriendStatus {
	if len(b.region) == 0 {
		return nil
	}
	return (*FriendStatus)(unsafe.Pointer(&b.region[0]))
}
func (b *FriendStatusBuilder) Region() []byte { return b.region }
