type FilesBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *FilesBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Files{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	FilesReset((*Files)(p))
	return true
}
func (b *FilesBuilder) GetRoot() *Files {
	if b.Arena.Locked {
		return nil
	}
	return (*Files)(b.Arena.At(b.root))
}
func (b *FilesBuilder) AsConst() *Files {
	if len(b.region) == 0 {
		return nil
	}
	return (*Files)(unsafe.Pointer(&b.region[0]))
}
func (b *FilesBuilder) Region() []byte { return b.region }
func (b *FilesBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), FilesTableType(), &b.Arena)
}
func (b *FilesBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), FilesTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *FilesBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), FilesTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *FilesBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// MeterReset restores Meter's declared defaults in place, reusing the storage
