const BeatLoadRetainBuilder = "Beat: retention requires a region round trip through the VARIABLE form"
const BeatSaveRetainMessages = "Beat: retention requires a region round trip through the VARIABLE form"

func BeatLoadRetain(region, wire []byte, retain *TableRetain, report *TableReport) *Beat {
	return (*Beat)(tableRegionLoadRetain(region, wire, BeatTableType(), BeatTableType().NodeType, 2, report, retain))
}
func BeatMeasureRetain(value *Beat, retain *TableRetain, allocator ...TableAllocator) int64 {
	return tableRegionSaveRetain(unsafe.Pointer(value), BeatTableType(), nil, true, retain, nil, allocator...)
}
func BeatSaveRetain(value *Beat, retain *TableRetain, buffer []byte, report *TableReport, allocator ...TableAllocator) int64 {
	if report == nil {
		return -1
	}
	return tableRegionSaveRetain(unsafe.Pointer(value), BeatTableType(), buffer, false, retain, report, allocator...)
}
func BeatMeasureBodyRetain(value *Beat, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !BeatSaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

func BeatSaveBodyRetain(w *TableRetainWriter, value *Beat) bool {
	if !BeatSaveBodyFieldsRetain(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
