type ServerRecordBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *ServerRecordBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(ServerRecord{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	ServerRecordReset((*ServerRecord)(p))
	return true
}
func (b *ServerRecordBuilder) GetRoot() *ServerRecord {
	if b.Arena.Locked {
		return nil
	}
	return (*ServerRecord)(b.Arena.At(b.root))
}
func (b *ServerRecordBuilder) AsConst() *ServerRecord {
	if len(b.region) == 0 {
		return nil
	}
	return (*ServerRecord)(unsafe.Pointer(&b.region[0]))
}
func (b *ServerRecordBuilder) Region() []byte { return b.region }
func (b *ServerRecordBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), ServerRecordTableType(), &b.Arena)
}
func (b *ServerRecordBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), ServerRecordTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *ServerRecordBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), ServerRecordTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *ServerRecordBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// LoginReset restores Login's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func LoginReset(value *Login) {
	value.Redis = 0
	value.User = 0
	value.Store = 0
	value.SeatAs = 0
	value.Key = 0
	value.Sops = 0
	value.SecretName = 0
}

func LoginMeasureBody(value *Login, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !LoginSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func LoginSaveBody(w *TableWriter, value *Login) bool {
	if !LoginSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
